-- quanto cursor cada sessao mantem aberto (dimensionar o cache):
SELECT ROUND(value) AS session_cached_cursors
FROM v$parameter WHERE name = 'session_cached_cursors';

SELECT MAX(value) AS pico_cursores_por_sessao
FROM v$sesstat s JOIN v$statname n ON n.statistic# = s.statistic#
WHERE n.name = 'session cursor cache count';
